    (1703101, 1, DATEADD(day, -30, @aujourdhui), ''09:00'', ''C17E'', NULL, 0), (1703102, 1, DATEADD(day, -31, @aujourdhui), ''09:00'', ''C17E'', NULL, 0),
    (1703103, 1, DATEADD(day, -25, @aujourdhui), ''14:00'', ''C17E'', NULL, 1), (1703104, 1, DATEADD(day, -24, @aujourdhui), ''09:00'', ''C17E'', NULL, 0),
